#!/usr/bin/env python3
"""Independent scoped check of PR4180's four-provider binding layer.

Re-checks the PR4088 fill under the mixed 109-mod selector with a code-disjoint
owner walk (same rules as PR4181's chronology), confirms helper-601's THREE=8 /
FOUR=7 width split, and cross-checks EVIDENCE.finite against that walk.
Does not rerun the 23-stage ordinary/outer release.

James Reed (@rcfc-jreed), with substantial AI assistance (Claude, in Cursor).
Apache-2.0.
"""
import argparse, collections, copy, gzip, json, subprocess, sys
from decimal import Decimal as D, getcontext
from fractions import Fraction as Q

HEAD = '15a4153e734a8d1d485c6d3bea9b1a8201328a4c'
BASE = '12fa8c5c844be21bfefb38a19503fbd867a11244'
PKG = 'research/mixed-provider-admission/'
PRED = 'research/staged544-mixed-fourth-entry/'
CALLS, REPLICAS, HELPERS = 3240, 360, 408
MASS = 65088 * REPLICAS
results = []


def check(name, ok, detail=''):
    results.append((name, bool(ok), detail))
    print(('PASS ' if ok else 'FAIL ') + name + ((': ' + str(detail)) if detail else ''), flush=True)
    return bool(ok)


def show(repo, path, rev=HEAD):
    return subprocess.run(['git', '-C', repo, 'show', f'{rev}:{path}'],
                          capture_output=True, check=True).stdout


def blob(repo, path, rev=HEAD):
    return subprocess.run(['git', '-C', repo, 'rev-parse', f'{rev}:{path}'],
                          capture_output=True, text=True, check=True).stdout.strip()


def js(b, gz=False):
    return json.loads(gzip.decompress(b) if gz else b)


def rref(vectors):
    pivots = {}
    for x in vectors:
        assert type(x) is int and 0 <= x < 512
        while x:
            p = x.bit_length() - 1
            if p in pivots:
                x ^= pivots[p]
            else:
                pivots[p] = x
                break
    for p in sorted(pivots):
        for q in list(pivots):
            if q > p and (pivots[q] >> p) & 1:
                pivots[q] ^= pivots[p]
    return frozenset(pivots.values())


FULL = rref([1 << j for j in range(9)])


def width(word, r):
    return len(rref(word['helper_final'].get(str(r), list(FULL)))) - len(rref(word['start_extra'].get(str(r), [])))


def load(repo):
    g = lambda p, rev=BASE: show(repo, p, rev)
    gb = lambda p, rev=BASE: blob(repo, p, rev)
    d = dict(
        evidence=js(show(repo, PKG + 'EVIDENCE.json', HEAD)),
        result=js(g(PRED + 'RESULT.json')),
        fill=js(g(PRED + 'owner/FILL.json.gz'), True),
        mixed=js(g(PRED + 'owner/MIXED-DISPATCH.json')),
        order=js(g(PRED + 'owner/ORDER.json')),
        template=js(g(PRED + 'owner/TEMPLATE.json.gz'), True),
        plan=js(g(PRED + 'owner/PLAN.json.gz'), True),
        old_dispatch=js(g(PRED + 'owner/DISPATCH.json')),
    )
    words, origins = {}, {}
    for tag, pid in [('base', 'gauge44'), ('extra', 'extra')]:
        origins[pid] = js(g(PRED + f'owner/old-NATIVE-{tag}.json.gz'), True)['helper_origin']
        for kind, suffix in [('THREE', ''), ('FOUR', '-four')]:
            words[pid + suffix] = js(g(PRED + f'inputs/{kind}-{tag}.json.gz'), True)
    d['words'], d['origins'] = words, origins
    d['blobs'] = {
        PKG + 'EVIDENCE.json': blob(repo, PKG + 'EVIDENCE.json', HEAD),
        PRED + 'owner/FILL.json.gz': gb(PRED + 'owner/FILL.json.gz'),
        PRED + 'owner/MIXED-DISPATCH.json': gb(PRED + 'owner/MIXED-DISPATCH.json'),
        PRED + 'RESULT.json': gb(PRED + 'RESULT.json'),
    }
    return d


def derive_windows(template, plan, order):
    clock = {tuple(v): t for t, v in enumerate(order)}
    children = {x['child']: x['rank'] for x in template['idle_children']}
    pair = {x['stage']: x['pair'] for x in template['recipe'] if x['kind'] == 'local'}
    family = {c: 2 * plan['pairs'][str(c)] + plan['sides'][str(c)] for c in children}
    windows = {}
    for o in range(REPLICAS):
        touched, tick = {}, None
        for e in template['execution_schedule']:
            k = e['kind']
            if k == 'local_cover_sweep':
                tick = clock[e['stage'], o]
                touched[pair[e['stage']]] = tick
            elif k == 'bridge':
                touched[e['src']] = tick
                touched[e['dst']] = tick
            elif k == 'idle_cover_sweep':
                for c in e['child_indices']:
                    if c in children:
                        windows[o, c] = (children[c], touched.get(e['pair'], -1), tick)
    return windows, family, clock


def walk(rows, order, provider, windows, family, widths, local):
    bad = collections.Counter()
    used = {}
    families = set()
    if len(rows) != CALLS * HELPERS:
        bad['role-count'] += 1
        return bad, {}, {}
    for j, row in enumerate(rows):
        t, h, o, c, p, z = row
        if t != j // HELPERS or h != j % HELPERS:
            bad['helper-identity'] += 1
        if h == 0:
            families = set()
        if (o, c) not in windows or not (0 <= p < 112):
            bad['bin'] += 1
            continue
        cap, lo, hi = windows[o, c]
        if not (lo < t <= hi):
            bad['window'] += 1
        f = (o, family[c], p)
        if f in families:
            bad['family'] += 1
        families.add(f)
        prefix = used.get((o, c, p), 0)
        if z != prefix:
            bad['offset'] += 1
        w = widths[provider[tuple(order[t])]][h]
        if prefix + w > cap:
            bad['capacity'] += 1
        used[o, c, p] = prefix + w
    idle = collections.Counter()
    for (o, c), (cap, lo, hi) in windows.items():
        for p in range(112):
            left = cap - used.get((o, c, p), 0)
            if left:
                idle[left] += 1
    profile = collections.Counter(idle)
    for call in order:
        profile.update(local[provider[tuple(call)]])
    return bad, dict(sorted(profile.items())), dict(sorted(idle.items()))


def run(d):
    order = [tuple(x) for x in d['order']]
    clock = {tuple(v): t for t, v in enumerate(order)}
    check('O1 ORDER covers 9 x 360 calls',
          len(order) == CALLS and set(clock) == {(s, r) for s in range(9) for r in range(REPLICAS)})

    expected = [[s, r, pid + ('-four' if clock[s, r] * 109 % 324 < 109 else '')]
                for s, r, pid in d['old_dispatch']]
    check('D1 MIXED-DISPATCH equals 109-mod fourth-entry selector', d['mixed'] == expected)
    provider = {(s, r): pid for s, r, pid in d['mixed']}
    counts = dict(collections.Counter(provider.values()))
    check('D2 provider counts match EVIDENCE.finite',
          counts == {k: v for k, v in d['evidence']['finite']['provider_counts'].items()},
          counts)

    widths, local = {}, {}
    for pid in ['gauge44', 'extra']:
        origin = d['origins'][pid]
        for suffix in ['', '-four']:
            key = pid + suffix
            w = d['words'][key]
            assert origin == sorted(set(range(224, 704)) - set(w['removed']))
            widths[key] = [width(w, r) for r in origin]
            local[key] = {int(k): v for k, v in w['report']['local_profile'].items()}

    idx = d['origins']['gauge44'].index(601)
    check('V1 helper 601 is owner-helper index 367 in both origins',
          idx == 367 and d['origins']['extra'].index(601) == 367)
    w601 = {k: widths[k][idx] for k in widths}
    check('V2 helper 601 widths: THREE=8, FOUR=7 (both orientations)',
          w601 == {'gauge44': 8, 'extra': 8, 'gauge44-four': 7, 'extra-four': 7}, w601)
    check('V3 FOUR start_extra[601] is the two-vector entrance [127,45]',
          d['words']['gauge44-four']['start_extra']['601'] == [127, 45]
          and d['words']['extra-four']['start_extra']['601'] == [127, 45]
          and d['words']['gauge44']['start_extra']['601'] == [45]
          and d['words']['extra']['start_extra']['601'] == [45])

    windows, family, _ = derive_windows(d['template'], d['plan'], order)
    rows = d['fill']['rows']
    check('F0 fill has 1,321,920 roles', len(rows) == CALLS * HELPERS)
    bad, profile, idle = walk(rows, order, provider, windows, family, widths, local)
    check('F1 literal binding walk: windows, families, compact offsets, capacity', not bad, dict(bad))
    check('F2 idle matches PR4088 RESULT and EVIDENCE.finite',
          idle == {int(k): v for k, v in d['result']['idle'].items()}
          == {int(k): v for k, v in d['evidence']['finite']['idle'].items()}, idle)
    check('P1 profile matches PR4088 RESULT and EVIDENCE.finite',
          profile == {int(k): v for k, v in d['result']['profile'].items()}
          == {int(k): v for k, v in d['evidence']['finite']['profile'].items()}, profile)
    check('P2 rank mass == 65088 * 360', sum(r * n for r, n in profile.items()) == MASS)

    # mass-neutral effect of the 601 width drop: each fourth call saves 1 idle unit of paid width
    n_four = sum(pid.endswith('-four') for pid in provider.values())
    check('A1 exactly 1090 fourth-entry calls (PR4088 selector)', n_four == 1090)
    # THREE width sum 3301, FOUR 3300 — one unit per fourth call
    check('A2 THREE/FOUR total width differ by 1 (the helper-601 drop)',
          sum(widths['extra']) - sum(widths['extra-four']) == 1
          and sum(widths['gauge44']) - sum(widths['gauge44-four']) == 1)

    # EVIDENCE claims
    fin = d['evidence']['finite']
    check('E1 EVIDENCE.finite roles/calls match',
          fin['roles'] == CALLS * HELPERS and fin['calls'] == CALLS)
    iso = d['evidence'].get('isolated_export_unchanged_after_replay')
    check('E2 EVIDENCE records PASS development release',
          d['evidence']['development_release']['status'] == 'PASS_REPLICA_ORDER_FILL_DERIVATIVE_COMPLETE_RELEASE',
          f'isolated_unchanged={iso}')

    # controls
    m = copy.deepcopy(rows)
    m[1][2:5] = m[0][2:5]
    b2, _, _ = walk(m, order, provider, windows, family, widths, local)
    check('C same-call family collision rejected', b2.get('family', 0) > 0, dict(b2))
    m = copy.deepcopy(rows)
    m[0][5] += 1
    b2, _, _ = walk(m, order, provider, windows, family, widths, local)
    check('C compact-offset hole rejected', b2.get('offset', 0) > 0, dict(b2))
    # force all calls to THREE widths: should break capacity somewhere because fill used FOUR widths on 1090 calls
    prov3 = {k: v.removesuffix('-four') for k, v in provider.items()}
    b2, _, _ = walk(rows, order, prov3, windows, family, widths, local)
    check('C stripping all -four (THREE widths on FOUR-sized fill) rejected',
          sum(b2.values()) > 0, dict(b2))
    # t < 1080 selector (PR4181) on this PR4088 fill
    prov1080 = {(s, r): pid + ('-four' if clock[s, r] < 1080 else '')
                for s, r, pid in d['old_dispatch']}
    b2, _, _ = walk(rows, order, prov1080, windows, family, widths, local)
    check('C PR4181 t<1080 selector on the PR4088 fill is rejected',
          sum(b2.values()) > 0, dict(b2))


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('--repo', required=True)
    ap.add_argument('--json')
    a = ap.parse_args()
    d = load(a.repo)
    for p, b in d['blobs'].items():
        print('blob', b, p)
    run(d)
    ok = all(r[1] for r in results)
    print(('PASS' if ok else 'FAIL'), f'{sum(r[1] for r in results)}/{len(results)} checks', flush=True)
    if a.json:
        open(a.json, 'w').write(json.dumps(
            dict(head=HEAD, blobs=d['blobs'],
                 checks=[dict(name=n, ok=o, detail=str(x)) for n, o, x in results]), indent=1))
    sys.exit(0 if ok else 1)


if __name__ == '__main__':
    main()
```
